import * as T from './three.module.js';
export function terrain(x,z){const d=Math.hypot(x-25,z+20);return .8*Math.sin(x*.032)*Math.cos(z*.042)+.3*Math.sin(z*.09+x*.035)+Math.max(0,d-85)*.027;}
export function buildEnvironment(scene,renderer,desktopDetail=false){
 let seed=8721;const random=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296;};
 const material=(color,roughness=1)=>new T.MeshStandardMaterial({color,roughness});
 const wood=material('#73614d'),bark=material('#685643'),stone=material('#8b8d80'),yellow=material('#d9ad36',.45),black=material('#283331',.5),white=material('#e5dfc9'),red=material('#bf4936');
 function mesh(g,m,x=0,y=0,z=0,parent=scene){const o=new T.Mesh(g,m);o.position.set(x,y,z);o.castShadow=true;o.receiveShadow=true;parent.add(o);return o;}
 function beam(a,b,r,m,parent=scene){const v=new T.Vector3().subVectors(b,a),o=mesh(new T.CylinderGeometry(r,r,v.length(),8),m,0,0,0,parent);o.position.copy(a).add(b).multiplyScalar(.5);o.quaternion.setFromUnitVectors(new T.Vector3(0,1,0),v.normalize());return o;}
 // World-space surface variation stays crisp close to the ground without a huge texture download.
 const noise=`float hash(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453);} float noise(vec2 p){vec2 i=floor(p),f=fract(p);f=f*f*(3.0-2.0*f);return mix(mix(hash(i),hash(i+vec2(1,0)),f.x),mix(hash(i+vec2(0,1)),hash(i+vec2(1,1)),f.x),f.y);}`;
 function textured(base,kind){const m=material(base);m.onBeforeCompile=s=>{s.vertexShader='varying vec3 vSurface;\n'+s.vertexShader;s.vertexShader=s.vertexShader.replace('#include <worldpos_vertex>','#include <worldpos_vertex>\nvSurface=(modelMatrix*vec4(transformed,1.0)).xyz;');s.fragmentShader='varying vec3 vSurface;\n'+noise+'\n'+s.fragmentShader;s.fragmentShader=s.fragmentShader.replace('#include <color_fragment>',`#include <color_fragment>\nfloat broad=noise(vSurface.xz*.19);float grain=noise(vSurface.xz*28.0);float detail=noise(vSurface.xz*3.0);diffuseColor.rgb *= mix(.65,1.17,broad)*mix(.72,1.17,grain)*mix(.87,1.08,detail);${kind==='grass'?'diffuseColor.rgb=mix(diffuseColor.rgb,vec3(.32,.27,.16),smoothstep(.62,.88,broad)*.38);':''}`);};m.customProgramCacheKey=()=>kind;return m;}
 const sky=new T.Mesh(new T.SphereGeometry(490,32,16),new T.ShaderMaterial({side:T.BackSide,depthWrite:false,vertexShader:'varying vec3 vSky; void main(){vSky=position;gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.0);}',fragmentShader:`varying vec3 vSky; ${noise} void main(){vec3 d=normalize(vSky);float h=max(d.y,0.0);vec3 col=mix(vec3(.78,.83,.79),vec3(.34,.56,.72),pow(h,.5));vec2 p=d.xz/max(d.y+.20,.10)*1.8;float cloud=noise(p)*.6+noise(p*2.2)*.28+noise(p*4.7)*.12;float amount=smoothstep(.49,.72,cloud)*smoothstep(.025,.16,d.y);col=mix(col,vec3(.96,.95,.89),amount*.75);gl_FragColor=vec4(col,1.0);}`}));scene.add(sky);
 const meadowTexture=new T.TextureLoader().load('./meadow.webp');meadowTexture.colorSpace=T.SRGBColorSpace;meadowTexture.wrapS=meadowTexture.wrapT=T.RepeatWrapping;meadowTexture.repeat.set(150,150);meadowTexture.anisotropy=Math.min(8,renderer.capabilities.getMaxAnisotropy());const meadowMaterial=textured('#c9c8aa','grass');meadowMaterial.map=meadowTexture;
 const geo=new T.PlaneGeometry(650,650,190,190);geo.rotateX(-Math.PI/2);const a=geo.attributes.position;for(let i=0;i<a.count;i++)a.setY(i,terrain(a.getX(i),a.getZ(i)));geo.computeVertexNormals();mesh(geo,meadowMaterial).castShadow=false;
 const road=new T.BufferGeometry(),verts=[],indices=[];for(let i=0;i<=180;i++){const z=115-i*2,x=-15+Math.sin(z*.025)*8;for(const side of [-1,1])verts.push(x+side*2.4,terrain(x+side*2.4,z)+.045,z);if(i<180){const k=i*2;indices.push(k,k+1,k+2,k+1,k+3,k+2);}}road.setAttribute('position',new T.Float32BufferAttribute(verts,3));road.setIndex(indices);road.computeVertexNormals();mesh(road,textured('#aaa18a','gravel')).castShadow=false;
 // Several bent, tapered blades per tuft; a single instanced draw call for the meadow.
 const gv=[],gi=[];for(let j=0;j<8;j++){const angle=j*2.4,h=.08+random()*.17,w=.004+random()*.004,bend=.025+random()*.06;const ux=Math.cos(angle),uz=Math.sin(angle),bx=Math.sin(angle)*bend,bz=Math.cos(angle)*bend,k=gv.length/3,ox=(random()-.5)*.14,oz=(random()-.5)*.14;const first=gv.length;gv.push(-ux*w,0,-uz*w,ux*w,0,uz*w,bx+ux*w*.45,h*.55,bz+uz*w*.45,bx-ux*w*.45,h*.55,bz-uz*w*.45,bx*1.6,h,bz*1.6);for(let n=first;n<gv.length;n+=3){gv[n]+=ox;gv[n+2]+=oz;}gi.push(k,k+1,k+2,k,k+2,k+3,k+3,k+2,k+4);}const gg=new T.BufferGeometry();gg.setAttribute('position',new T.Float32BufferAttribute(gv,3));gg.setIndex(gi);gg.computeVertexNormals();const gm=new T.MeshStandardMaterial({color:'#d5d6a9',side:T.DoubleSide,roughness:1});const tuftCount=desktopDetail?44000:26000;const grass=new T.InstancedMesh(gg,gm,tuftCount),dummy=new T.Object3D();for(let i=0;i<tuftCount;i++){let x,z;if(i%3===0){const radius=Math.sqrt(random())*24,angle=random()*Math.PI*2;x=Math.sin(angle)*radius;z=Math.cos(angle)*radius;}else{x=random()*110-20;z=random()*110-75;}if(Math.hypot(x,z)<1.4)x+=2;if(Math.abs(x-(-15+Math.sin(z*.025)*8))<2.8)x+=6;dummy.position.set(x,terrain(x,z),z);dummy.rotation.set(0,random()*Math.PI*2,0);dummy.scale.setScalar(.7+random()*.6);dummy.updateMatrix();grass.setMatrixAt(i,dummy.matrix);grass.setColorAt(i,new T.Color().setHSL(.17+random()*.07,.2+random()*.14,.40+random()*.19));}grass.receiveShadow=true;scene.add(grass);seed=56021;
 // Alpha-tested branch clusters replace the solid cone and ball canopies.
 const leafTexture=new T.TextureLoader().load('./foliage.webp');leafTexture.colorSpace=T.SRGBColorSpace;leafTexture.anisotropy=Math.min(4,renderer.capabilities.getMaxAnisotropy());
 const leaves=new T.InstancedMesh(new T.PlaneGeometry(1,1),new T.MeshStandardMaterial({map:leafTexture,alphaTest:.4,side:T.DoubleSide,roughness:1,color:'#b4c79b'}),2800);let count=0;
 function tree(x,z,size=1){const y=terrain(x,z);mesh(new T.CylinderGeometry(.10*size,.30*size,5.4*size,9),bark,x,y+2.7*size,z);for(let b=0;b<5;b++){const an=b*2.4,tip=new T.Vector3(x+Math.sin(an)*1.9*size,y+(4.4+random()*1.8)*size,z+Math.cos(an)*1.9*size);beam(new T.Vector3(x,y+3.2*size,z),tip,.075*size,bark);}for(let j=0;j<24;j++){const an=random()*Math.PI*2,r=Math.sqrt(random())*2.8*size,yy=(4.3+random()*3)*size;dummy.position.set(x+Math.sin(an)*r,y+yy,z+Math.cos(an)*r);dummy.rotation.set((random()-.5)*1.7,random()*Math.PI*2,(random()-.5)*.6);dummy.scale.set(3.4*size,2.7*size,1);dummy.updateMatrix();leaves.setMatrixAt(count,dummy.matrix);leaves.setColorAt(count,new T.Color().setHSL(.20+random()*.06,.12+random()*.12,.57+random()*.21));count++;}}
 for(let i=0;i<90;i++){const x=random()*370-155,z=random()*290-210;if(x>-12&&x<85&&z>-75&&z<32)continue;tree(x,z,.8+random()*1.1);}tree(-7,-15,.95);tree(76,-38,1.2);tree(26,32,1.1);leaves.count=count;leaves.castShadow=true;leaves.receiveShadow=true;scene.add(leaves);
 const rockGeo=new T.IcosahedronGeometry(1,2);const rp=rockGeo.attributes.position;for(let i=0;i<rp.count;i++){const v=new T.Vector3().fromBufferAttribute(rp,i);const f=.85+.18*Math.sin(v.x*12+v.y*7)*Math.cos(v.z*9);rp.setXYZ(i,v.x*f,v.y*f,v.z*f);}rockGeo.computeVertexNormals();const rockMat=textured('#8c8e80','stone');for(let i=0;i<95;i++){const x=random()*190-55,z=random()*180-105;if(x>-3&&x<70&&z>-60&&z<20)continue;const o=mesh(rockGeo,rockMat,x,terrain(x,z)+.15,z);o.scale.set(.4+random()*2.2,.3+random(),.4+random()*1.7);o.rotation.y=random()*6;}mesh(rockGeo,rockMat,-2,terrain(-2,3),3).scale.set(.7,.45,.8);
 // Timber rails, weathered boards, roof ribs, doors and a small silo.
 for(let i=0;i<23;i++){const x=-22+i*5,z=-78,y=terrain(x,z);mesh(new T.BoxGeometry(.20,1.6,.20),wood,x,y+.75,z);if(i<22)for(const h of [.55,1.15])beam(new T.Vector3(x,y+h,z),new T.Vector3(x+5,terrain(x+5,z)+h,z),.055,wood);}
 const barn=new T.Group();barn.position.set(50,terrain(50,-112),-112);scene.add(barn);mesh(new T.BoxGeometry(19,7,12),material('#704b3f'),0,3.5,0,barn);const roof=material('#787c79',.65);for(const s of [-1,1]){const o=mesh(new T.BoxGeometry(21,.18,7.7),roof,0,8.2,s*3.3,barn);o.rotation.x=s*.48;for(let k=-10;k<=10;k++){const rib=mesh(new T.BoxGeometry(.055,.10,7.7),roof,k,8.3,s*3.3,barn);rib.rotation.x=s*.48;}}for(let x=-9;x<=9;x+=.5)mesh(new T.BoxGeometry(.035,7,.035),material('#a17c65'),x,3.5,6.02,barn);mesh(new T.BoxGeometry(5,4.8,.16),wood,0,2.4,6.1,barn);for(const x of [-6,6]){mesh(new T.BoxGeometry(2.1,2.3,.12),white,x,4.6,6.1,barn);mesh(new T.BoxGeometry(1.8,2,.14),black,x,4.6,6.2,barn);}mesh(new T.CylinderGeometry(2.1,2.1,12,20),material('#a8a79b',.6),-14,6,0,barn);mesh(new T.SphereGeometry(2.1,20,10,0,Math.PI*2,0,Math.PI/2),roof,-14,12,0,barn);
 const treeTexture=new T.TextureLoader().load('./oak-tree.webp');treeTexture.colorSpace=T.SRGBColorSpace;treeTexture.anisotropy=Math.min(4,renderer.capabilities.getMaxAnisotropy());const distantTreeGeometry=new T.PlaneGeometry(1,1);distantTreeGeometry.translate(0,.5,0);
 // Each forest layer follows the same sampled hillside surface as its ridge mesh.
 function hillHeight(x,z,layer){const edge=Math.max(0,1-Math.pow(z/75,2));return edge*(28+layer*12+15*Math.sin(x*.018+layer*2)+9*Math.cos(x*.039+layer)+2.4*Math.sin(x*.13+z*.09));}
 for(let layer=0;layer<3;layer++){
 const ridge=new T.PlaneGeometry(900,150,140,28);ridge.rotateX(-Math.PI/2);const p=ridge.attributes.position;for(let i=0;i<p.count;i++)p.setY(i,hillHeight(p.getX(i),p.getZ(i),layer));ridge.computeVertexNormals();const o=mesh(ridge,textured(['#607355','#71866c','#8da18d'][layer],'hill'+layer),0,0,-220-layer*65);o.castShadow=false;
 const n=desktopDetail?1700:1000,forest=new T.InstancedMesh(distantTreeGeometry,new T.MeshStandardMaterial({map:treeTexture,alphaTest:.45,side:T.DoubleSide,roughness:1,color:['#afbaa6','#b5c2b1','#bbcbbf'][layer]}),n*2);
 for(let i=0;i<n;i++){const x=random()*860-430,z=(random()-.5)*130,h=7+random()*6;dummy.position.set(x,hillHeight(x,z,layer)-.15,z-220-layer*65);dummy.scale.set(h*(.7+random()*.15),h,1);for(let side=0;side<2;side++){dummy.rotation.set(0,side*Math.PI/2+(random()-.5)*.25,0);dummy.updateMatrix();forest.setMatrixAt(i*2+side,dummy.matrix);forest.setColorAt(i*2+side,new T.Color().setHSL(.22,.06,.72+random()*.20));}}scene.add(forest);}

 function roundedBox(w,h,d,r){const shape=new T.Shape(),x=-w/2,y=-h/2;shape.moveTo(x+r,y);shape.lineTo(x+w-r,y);shape.quadraticCurveTo(x+w,y,x+w,y+r);shape.lineTo(x+w,y+h-r);shape.quadraticCurveTo(x+w,y+h,x+w-r,y+h);shape.lineTo(x+r,y+h);shape.quadraticCurveTo(x,y+h,x,y+h-r);shape.lineTo(x,y+r);shape.quadraticCurveTo(x,y,x+r,y);const g=new T.ExtrudeGeometry(shape,{depth:d-2*r,bevelEnabled:true,bevelSize:r,bevelThickness:r,bevelSegments:3,steps:1,curveSegments:5});g.translate(0,0,-(d-2*r)/2);return g;}
 // Physical total station: tripod braces, tribrach, yoke, telescope, glass, keypad, knobs.
 const stationY=terrain(0,0),instrument=new T.Group();instrument.position.y=stationY;scene.add(instrument);
 for(let i=0;i<3;i++){const an=i*Math.PI*2/3;const low=new T.Vector3(Math.sin(an)*.7,.05,Math.cos(an)*.7),top=new T.Vector3(Math.sin(an)*.15,1.43,Math.cos(an)*.15);beam(low,top,.037,yellow,instrument);beam(low.clone().lerp(top,.1),top.clone().lerp(low,.45),.018,black,instrument);beam(new T.Vector3(0,.9,0),low.clone().lerp(top,.42),.014,black,instrument);}
 mesh(new T.CylinderGeometry(.22,.25,.10,28),black,0,1.43,0,instrument);mesh(new T.CylinderGeometry(.16,.19,.13,28),yellow,0,1.54,0,instrument);for(let i=0;i<3;i++){const an=i*2.094;mesh(new T.CylinderGeometry(.04,.04,.055,16),black,Math.sin(an)*.19,1.49,Math.cos(an)*.19,instrument);}
 const body=mesh(roundedBox(.46,.30,.30,.02),yellow,0,1.76,0,instrument);
 for(const side of [-1,1])mesh(roundedBox(.065,.45,.22,.01),yellow,side*.23,2.0,-.015,instrument);mesh(roundedBox(.47,.045,.16,.01),black,0,2.24,-.01,instrument);
 mesh(new T.CylinderGeometry(.135,.135,.40,32),black,0,2.03,-.005,instrument).rotation.x=Math.PI/2;const glass=new T.MeshStandardMaterial({color:'#244647',metalness:.8,roughness:.1});mesh(new T.CylinderGeometry(.115,.115,.013,32),glass,0,2.03,.203,instrument).rotation.x=Math.PI/2;mesh(new T.TorusGeometry(.119,.012,8,32),yellow,0,2.03,.212,instrument);
 const panel=mesh(roundedBox(.42,.26,.045,.008),black,0,1.75,.174,instrument);panel.rotation.x=-.12;
 const displayCanvas=document.createElement('canvas');displayCanvas.width=512;displayCanvas.height=256;const ctx=displayCanvas.getContext('2d');ctx.fillStyle='#c5d1bf';ctx.fillRect(0,0,512,256);ctx.fillStyle='#253c34';ctx.font='bold 27px monospace';ctx.fillText('FIELD SURVEY',22,43);ctx.font='25px monospace';ctx.fillText('STATION  P1',22,91);ctx.fillText('Hz   000.00°',22,137);ctx.fillText('HD   ---- m',22,180);ctx.font='19px monospace';ctx.fillText('SIGHT  •  RECORD',22,229);const screenTex=new T.CanvasTexture(displayCanvas);screenTex.colorSpace=T.SRGBColorSpace;mesh(new T.PlaneGeometry(.28,.20),new T.MeshBasicMaterial({map:screenTex}),-.05,1.765,.201,instrument);
 for(let row=0;row<4;row++)for(let col=0;col<2;col++)mesh(new T.BoxGeometry(.035,.028,.012),row===3?yellow:white,.125+col*.045,1.85-row*.05,.208,instrument);
 for(const side of [-1,1]){const knob=mesh(new T.CylinderGeometry(.047,.047,.07,20),black,side*.29,1.78,0,instrument);knob.rotation.z=Math.PI/2;}const ring=mesh(new T.TorusGeometry(1.1,.026,8,64),new T.MeshBasicMaterial({color:'#e4b668',transparent:true,opacity:.7}),0,stationY+.075,0);ring.rotation.x=-Math.PI/2;
 return {instrument,ring,stationY,mesh,material,white,red,yellow};
}
